    static class Solution {
        public int longestBalanced(int[] nums) {
            var map = new HashMap<String,Boolean>();
            if (nums.length == 1) return 0;
            int i = 0, j = 1, longest = 0, k = 1;
            var evenOdd = new int[2];
            var set = new int[100000];
            while (j < nums.length) {
                while (j < nums.length) {
                    evenOdd[0] = 0;
                    evenOdd[1] = 0;
                    if(!map.containsKey(i+","+j)){
                        map.put(i+","+j,isBalanced(nums, i, j, evenOdd, set));
                    }
                    if (map.get(i+","+j)) {
                        if (longest < j + 1 - i) {
                            longest = j + 1 - i;
                            break;
                        }
                    }
                    i++;
                    j++;
                }
                i = 0;
                j = ++k;

            }
            System.out.println(map);
            return longest;
        }


        boolean isBalanced(int[] nums, int i, int j, int[] evenOdd, int[] set) {
            for (int k = i; k <= j; k++) {
                if (set[nums[k]] == 0) {
                    set[nums[k]]++;
                    evenOdd[nums[k] % 2]++;
                }
            }
            for (int k = i; k <= j; k++) {
                set[nums[k]] = 0;
            }
            return evenOdd[0] == evenOdd[1];
        }
    }
